import {sections,fields,lists,teams,validate,blank} from './schema.mjs';
const $=id=>document.getElementById(id);
let token='',repoInfo=null,sha='',content=null,saved='',busy=false;
const labels={shortName:'Navigation name',intro:'Introduction',portrait:'Portrait path or URL',photo:'Photo path or URL',universityUrl:'University profile URL',orcidUrl:'ORCID URL',scholarUrl:'Google Scholar URL',listUrl:'Full publication list URL',googleSiteUrl:'Google Site URL',text:'Biography',enquiries:'Enquiry text',link:'Profile link',url:'Link URL',note:'Additional details',label:'Section label',role:'Role / degree',research:'Research area / project'};
const longFields=['text','intro','description','address','research','enquiries'];
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function button(text,action,cls){const b=el('button',text,cls);b.type='button';b.addEventListener('click',action);return b;}
function message(text,error=false){$('notice').textContent=text;$('notice').className='notice'+(error?' error':'');$('notice').hidden=false;}
function dirty(){return content&&JSON.stringify(content)!==saved;}
function update(){ $('save').disabled=busy||!dirty();$('save-state').textContent=dirty()?'Unsaved changes':'All changes saved';}
function lock(value){busy=value;$('editor-fields').disabled=value;$('disconnect').disabled=value;update();}
function endpoint(){return 'https://api.github.com/repos/'+encodeURIComponent(repoInfo.owner)+'/'+encodeURIComponent(repoInfo.repo)+'/contents/data/content.json';}
async function api(url,options={}){const res=await fetch(url,{...options,headers:{Accept:'application/vnd.github+json',Authorization:'Bearer '+token,'X-GitHub-Api-Version':'2026-03-10',...options.headers}});const data=await res.json();if(!res.ok){const meanings={401:'The GitHub token is invalid or expired.',403:'GitHub denied access. Check token permissions, repository rules, and API limits.',404:'Repository, branch, or data/content.json not found. Check your details and token access.',409:'The content changed in GitHub. Your unsaved edits are still here. Copy them before reconnecting to load the latest version.',422:'GitHub could not save. Check branch rules and whether direct commits are allowed.'};throw Error(meanings[res.status]||'GitHub request failed. Please try again.');}return data;}
function decode(value){return new TextDecoder().decode(Uint8Array.from(atob(value.replace(/\s/g,'')),x=>x.charCodeAt(0)));}
function encode(value){let binary='';for(const b of new TextEncoder().encode(value))binary+=String.fromCharCode(b);return btoa(binary);}
function makeFields(section,item,index){const grid=el('div',undefined,'field-grid');for(const key of fields[section]){const container=el('div',undefined,'field'+(longFields.includes(key)?' full':''));const id=section+'-'+(index??'main')+'-'+key;const label=el('label',labels[key]||key[0].toUpperCase()+key.slice(1));label.htmlFor=id;let input;if(key==='category'){input=el('select');for(const [value,title] of teams){const option=el('option',title);option.value=value;input.append(option);}}else{input=el(longFields.includes(key)?'textarea':'input');if(input.tagName==='INPUT')input.type=key==='email'?'email':'text';else input.rows=key==='text'?7:3;}input.id=id;input.value=item[key];input.addEventListener('input',()=>{item[key]=input.value;update();});if(key==='category')input.addEventListener('change',render);container.append(label,input);grid.append(container);}return grid;}
function record(section,item,index){const box=el('div',undefined,'edit-record');const heading=el('div',undefined,'record-heading');heading.append(el('h3',item.name||item.title||item.degree||'New entry'));const actions=el('div',undefined,'record-actions');const peers=content[section].map((v,i)=>({v,i})).filter(({v})=>section!=='members'||v.category===item.category);const pos=peers.findIndex(p=>p.i===index);for(const [text,offset] of [['↑',-1],['↓',1]]){const b=button(text,()=>{const other=peers[pos+offset].i;[content[section][index],content[section][other]]=[content[section][other],content[section][index]];render();});b.disabled=pos+offset<0||pos+offset>=peers.length;b.setAttribute('aria-label',offset===-1?'Move entry up':'Move entry down');actions.append(b);}actions.append(button('Remove',()=>{if(confirm('Remove this entry? It will be removed from the published site after you save.')){content[section].splice(index,1);render();}},'remove'));heading.append(actions);box.append(heading,makeFields(section,item,index));return box;}
function add(section,category){content[section].push(blank(section,category));render();const index=content[section].length-1;$(section+'-'+index+'-'+fields[section][0])?.focus();}
function render(){const host=$('editor-fields');host.replaceChildren();$('section-nav').replaceChildren();for(const [section,title] of Object.entries(sections)){const nav=el('a',title);nav.href='#edit-'+section;$('section-nav').append(nav);const box=el('section',undefined,'edit-section');box.id='edit-'+section;box.append(el('h2',title));if(section==='members'){for(const [category,title,id,singular] of teams){const team=el('section',undefined,'team-editor-section');team.id='team-'+id;team.append(el('h3',title));const members=content.members.map((v,i)=>({v,i})).filter(({v})=>v.category===category);if(!members.length)team.append(el('p','No members added yet.','editor-help team-no-members'));for(const {v,i} of members)team.append(record(section,v,i));team.append(button('+ Add '+singular,()=>add(section,category),'add-button'));box.append(team);}}else if(lists.includes(section)){for(const [i,item] of content[section].entries())box.append(record(section,item,i));box.append(button('+ Add entry',()=>add(section),'add-button'));}else box.append(makeFields(section,content[section]));host.append(box);}update();}
$('connect-form').addEventListener('submit',async event=>{event.preventDefault();const submit=event.submitter;submit.disabled=true;try{const owner=$('owner').value.trim(),repo=$('repo').value.trim(),branch=$('branch').value.trim();if(!/^[a-zA-Z0-9-]+$/.test(owner)||!/^[a-zA-Z0-9_.-]+$/.test(repo)||!branch)throw Error('Enter a valid username, repository and branch.');repoInfo={owner,repo,branch};token=$('token').value.trim();$('token').value='';const data=await api(endpoint()+'?ref='+encodeURIComponent(branch));if(data.encoding!=='base64'||!data.content)throw Error('GitHub did not return editable content.');content=validate(JSON.parse(decode(data.content)));sha=data.sha;saved=JSON.stringify(content);render();$('connection').hidden=true;$('workspace').hidden=false;$('disconnect').hidden=false;$('repository-name').textContent=owner+'/'+repo+' · '+branch;$('build-status').href='https://github.com/'+encodeURIComponent(owner)+'/'+encodeURIComponent(repo)+'/actions';message('Connected. Edit content below.');}catch(error){token='';message(error.message,true);}finally{submit.disabled=false;}});
$('save').addEventListener('click',async()=>{lock(true);try{validate(content);const snapshot=JSON.stringify(content);const data=await api(endpoint(),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:'Update academic site content',content:encode(JSON.stringify(content,null,2)+'\n'),sha,branch:repoInfo.branch})});sha=data.content.sha;saved=snapshot;message('Saved to GitHub. Publication is pending until the GitHub Pages workflow succeeds. Use View publishing status to check.');}catch(error){message(error.message,true);}finally{lock(false);}});
$('disconnect').addEventListener('click',()=>{if(dirty()&&!confirm('Discard unsaved edits and disconnect?'))return;token='';content=null;saved='';sha='';$('editor-fields').replaceChildren();$('workspace').hidden=true;$('disconnect').hidden=true;$('connection').hidden=false;message('Disconnected. Your token has been cleared.');});
$('editor').addEventListener('submit',e=>e.preventDefault());
window.addEventListener('beforeunload',event=>{if(dirty()){event.preventDefault();event.returnValue='';}});
try{const config=await(await fetch('../site.config.json')).json();for(const key of ['owner','repo','branch'])$(key).value=config[key]||'';}catch{message('Enter your GitHub repository details to connect.');}
